"""Private read-only review of self-entered race results.

Serves HTML, CSS and JS only. No personal records or licensed data in Python.
All accounting, forecasts and results are read locally inside the owner's browser.
"""

HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#09172b\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><title>競馬ナイン｜着順ごとの振り返り</title><link rel=\"stylesheet\" href=\"/owner-review.css\"></head><body><main><a href=\"/\">← 本人用ホーム</a><h1>🏇 着順ごとの振り返り</h1><p class=\"warning\">本人が入力した着順メモと買い目の比較です。JRA公式結果の取得・照合や、実際の馬券購入・払戻の証明ではありません。過去の買い目を検証するだけで、次のレースの的中・回収率を保証しません。</p><section><h2>集計範囲</h2><div class=\"filters\"><div><label for=\"reviewScope\">対象期間</label><select id=\"reviewScope\"><option value=\"all\">保存済みの全期間</option><option value=\"day\">選択日だけ</option></select></div><div><label for=\"reviewDate\">開催日</label><input id=\"reviewDate\" type=\"date\"></div></div><button id=\"reviewRefresh\" type=\"button\">端末内の記録を再集計</button><p class=\"muted\">Safariとホーム画面版は別の保存領域になることがあります。実際に入力したアプリで開いてください。</p><p id=\"reviewStatus\" role=\"status\" class=\"muted\">記録を確認しています。</p></section><section><h2>予想下書きの比較</h2><p class=\"muted\">1つの開催日・競馬場・Rにつき保存済み下書き1件で集計。未購入の予想も含みます。購入記録とは合算しません。</p><div id=\"reviewDraftStats\" class=\"stats\" role=\"region\" aria-label=\"予想下書きの候補別成績\"></div></section><section><h2>購入した組み合わせの比較（本人入力）</h2><p class=\"muted\">実購入として本人が登録した買い目を、レース内の同一フォーメーションごとに集計。重複購入は同じ予想1件と扱います。購入額・払戻・回収率はここで計算しません。</p><div id=\"reviewPurchaseStats\" class=\"stats\" role=\"region\" aria-label=\"購入の自己申告記録の候補別成績\"></div></section><section><h2>レース別・取りこぼしの原因</h2><p id=\"reviewCoverage\" class=\"muted\"></p><div id=\"reviewDetails\" role=\"region\" aria-label=\"レース別の着順分析\"></div><p class=\"muted\">判定の優先順位ではなく、1着・2着・3着をそれぞれ独立して判定します。「1着候補から漏れ（別着順に評価あり）」は、勝ち馬が2着・3着候補にいても1着候補に選べなかったケースです。</p><a href=\"/my-tickets#savedPanel\">3連単の下書き・着順メモを入力</a><p><a href=\"/owner-backup\">5種類の記録をバックアップ</a></p></section></main><script src=\"/owner-review.js\" defer></script></body></html>"
CSS = "*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#ecf4ff;font:15px/1.6 system-ui,sans-serif}main{max-width:760px;margin:auto;padding:19px 13px 48px}h1{font-size:25px;margin:14px 0}h2{font-size:19px;margin:0 0 7px}a{color:#efce7b}p{overflow-wrap:anywhere}section{background:#152b44;border:1px solid #476582;border-radius:14px;padding:14px;margin:14px 0}.warning{padding:11px;border:1px solid #a28a60;background:#322a24;color:#ffe9b7;border-radius:11px;font-size:13px}.muted{font-size:13px;color:#c8d6e5}.filters{display:grid;grid-template-columns:1fr 1fr;gap:10px}.filters label{display:block;font-weight:700}.filters select,.filters input,button{font:inherit;border:1px solid #8097ac;border-radius:9px;background:#0b2036;color:#f9fcff;padding:9px;min-height:45px;width:100%}button{margin-top:12px;background:#e8c573;color:#132a41;border:0;font-weight:800}button:focus-visible,a:focus-visible{outline:3px solid #ead188}.stats{border:1px solid #496883;padding:10px;border-radius:10px;background:#0e2237}.stats strong{color:#f4da97}.stat-item{padding:5px 1px;font-size:14px}.review-row{background:#0e2238;border:1px solid #496581;border-radius:11px;margin:10px 0;padding:11px}.review-row strong{display:block;color:#f4d48a;font-size:16px}.review-row p{font-size:13px;line-height:1.7;margin:5px 0}.good{color:#b7efc8}.miss{color:#ffcfaa}.error{color:#ffbca9}.review-picks{font-variant-numeric:tabular-nums}@media(max-width:450px){.filters{grid-template-columns:1fr}}"
JS = "(()=>{'use strict';\n// No fetch/XHR, no storage writes and no automatic source verification.\nconst DRAFT='keiba-nine-owner-ticket-drafts-v1';\nconst PURCHASE='keiba-nine-owner-real-purchases-v1';\nconst TRACKS=['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'];\nconst $=id=>document.getElementById(id);\nconst key=x=>x.date+'|'+x.track+'|'+x.race;\nconst orderSet=a=>[...a].sort((x,y)=>x-y).join(',');\nconst formKey=x=>['first','second','third'].map(k=>orderSet(x[k])).join('/');\nfunction dateOK(s){\n if(typeof s!=='string'||!/^20\\d{2}-\\d{2}-\\d{2}$/.test(s))return false;\n const d=new Date(s+'T12:00:00Z');\n return Number.isFinite(d.valueOf())&&d.toISOString().slice(0,10)===s;\n}\nfunction numbers(x){return Array.isArray(x)&&x.length<=18&&\n x.every(n=>Number.isInteger(n)&&n>=1&&n<=18)&&new Set(x).size===x.length;}\nfunction finish(x){return Array.isArray(x)&&x.length===3&&\n x.every(n=>Number.isInteger(n)&&n>=1&&n<=18)&&new Set(x).size===3;}\nfunction points(r){\n const a=new Set();\n for(const i of r.first)for(const j of r.second)for(const k of r.third)\n  if(i!==j&&j!==k&&i!==k)a.add(i+'-'+j+'-'+k);\n return a.size;\n}\nfunction basic(r){\n return r&&typeof r==='object'&&dateOK(r.date)&&TRACKS.includes(r.track)&&\n  Number.isInteger(r.race)&&r.race>=1&&r.race<=12&&\n  ['first','second','third'].every(k=>numbers(r[k]))&&\n  points(r)>=1&&points(r)<=48&&\n  (!Object.prototype.hasOwnProperty.call(r,'result')||\n    r.result===null||finish(r.result));\n}\nfunction validDraft(r){return basic(r)&&typeof r.savedAt==='string'&&r.savedAt.length<=32;}\nfunction validPurchase(r){\n return basic(r)&&typeof r.id==='string'&&/^[a-z0-9-]{1,80}$/.test(r.id)&&\n  Number.isSafeInteger(r.unit)&&r.unit>=100&&r.unit<=100000&&r.unit%100===0&&\n  Number.isSafeInteger(r.stake)&&r.stake===points(r)*r.unit&&\n  (r.payout===null||(Number.isSafeInteger(r.payout)&&r.payout>=0))&&\n  typeof r.purchasedAt==='string'&&r.purchasedAt.length<=32;\n}\nfunction readRows(name,max,valid,identity){\n const raw=localStorage.getItem(name);\n if(raw&&raw.length>2500000)throw Error('保存内容が大きすぎます。');\n const rows=JSON.parse(raw||'[]');\n if(!Array.isArray(rows)||rows.length>max||!rows.every(valid)||\n   new Set(rows.map(identity)).size!==rows.length)\n  throw Error(name===DRAFT?'予想下書きの形式や重複を確認してください。':\n    '購入記録の金額・形式・重複を確認してください。');\n return rows;\n}\nfunction statRows(target,arr){\n target.replaceChildren();\n const compared=arr.filter(x=>x.status==='reviewed');\n const total=arr.length,n=compared.length;\n const hit=k=>compared.filter(x=>x[k]).length;\n const missedFirst=compared.filter(x=>!x.first);\n const partialFirst=missedFirst.filter(x=>x.winnerSeen).length;\n const labels=[\n  '結果を比較できた予想：'+n+'件／'+total+'件',\n  '1着馬を1着候補に入れた：'+hit('first')+'／'+n+'件',\n  '2着馬を2着候補に入れた：'+hit('second')+'／'+n+'件',\n  '3着馬を3着候補に入れた：'+hit('third')+'／'+n+'件',\n  '3連単の組み合わせ内：'+hit('exact')+'／'+n+'件',\n  '勝ち馬が1着候補外：'+missedFirst.length+'件（2・3着候補にはいた：'+partialFirst+'件）'\n ];\n for(const label of labels){\n  const p=document.createElement('div');p.className='stat-item';\n  p.textContent=label;target.append(p);\n }\n if(!n){const p=document.createElement('p');p.className='muted';\n  p.textContent='まだ比較可能な着順メモがありません。0％や外れとは扱いません。';target.append(p);}\n}\nfunction verdict(form,result){\n if(!finish(result))return {status:'pending'};\n const first=form.first.includes(result[0]),second=form.second.includes(result[1]),\n   third=form.third.includes(result[2]);\n return {status:'reviewed',first,second,third,exact:first&&second&&third,\n  winnerSeen:!first&&(form.second.includes(result[0])||form.third.includes(result[0]))};\n}\nfunction statusText(x){\n if(x.status==='conflict')return '複数の着順メモが不一致のため照合保留';\n if(x.status==='pending')return '着順メモ未入力・判定保留';\n return ['1着 '+(x.first?'候補内':'候補外'+(x.winnerSeen?'（2・3着候補にあり）':'')),\n  '2着 '+(x.second?'候補内':'候補外'),\n  '3着 '+(x.third?'候補内':'候補外'),\n  '3連単 '+(x.exact?'組み合わせ内':'組み合わせ外')].join('／');\n}\nfunction makeData(drafts,purchases,scope,day){\n const groups=new Map();\n for(const r of drafts.concat(purchases)){\n  if(scope==='day'&&r.date!==day)continue;\n  const k=key(r);\n  if(!groups.has(k))groups.set(k,{date:r.date,track:r.track,race:r.race,draft:null,purchases:[]});\n  if(drafts.includes(r))groups.get(k).draft=r;\n  else groups.get(k).purchases.push(r);\n }\n const draftsEvaluated=[],purchasesEvaluated=[],details=[];\n let conflicts=0,pending=0;\n for(const group of groups.values()){\n  const possibilities=[group.draft,...group.purchases].filter(Boolean).map(r=>r.result).filter(finish);\n  const outcomes=new Set(possibilities.map(r=>r.join('-')));\n  const conflict=outcomes.size>1;\n  if(conflict)conflicts++;\n  const outcome=!conflict&&possibilities.length?possibilities[0]:null;\n  if(!outcome&&!conflict)pending++;\n  const parts=[];\n  if(group.draft){\n   const v=conflict?{status:'conflict'}:verdict(group.draft,outcome);\n   draftsEvaluated.push(v);\n   parts.push({name:'予想下書き',form:group.draft,v});\n  }\n  const forms=new Map();\n  for(const r of group.purchases){\n   const signature=formKey(r);\n   if(!forms.has(signature))forms.set(signature,{form:r,count:0});\n   forms.get(signature).count++;\n  }\n  for(const {form,count} of forms.values()){\n   const v=conflict?{status:'conflict'}:verdict(form,outcome);\n   purchasesEvaluated.push(v);\n   parts.push({name:'実購入の自己申告'+(count>1?'・同一買い目'+count+'件':''),form,v});\n  }\n  details.push({group,parts,outcome,conflict});\n }\n details.sort((a,b)=>b.group.date.localeCompare(a.group.date)||\n  TRACKS.indexOf(a.group.track)-TRACKS.indexOf(b.group.track)||a.group.race-b.group.race);\n return {draftsEvaluated,purchasesEvaluated,details,conflicts,pending};\n}\nfunction show(){\n $('reviewStatus').textContent='端末内の記録を読み込み中です。';\n $('reviewDraftStats').replaceChildren();$('reviewPurchaseStats').replaceChildren();\n $('reviewDetails').replaceChildren();$('reviewCoverage').textContent='';\n try{\n  const drafts=readRows(DRAFT,300,validDraft,key);\n  const purchases=readRows(PURCHASE,500,validPurchase,x=>x.id);\n  const scope=$('reviewScope').value,day=$('reviewDate').value;\n  if(scope==='day'&&!dateOK(day))throw Error('開催日を正しく選んでください。');\n  const model=makeData(drafts,purchases,scope,day);\n  statRows($('reviewDraftStats'),model.draftsEvaluated);\n  statRows($('reviewPurchaseStats'),model.purchasesEvaluated);\n  const total=model.details.length;\n  $('reviewStatus').textContent='対象 '+total+'R／結果の未入力 '+model.pending+'R／'+\n   '着順メモ不一致 '+model.conflicts+'R。購入・払戻額は変更していません。';\n  $('reviewCoverage').textContent=total>60?\n   '新しい日付から60Rを表示（集計は対象全R）。日付を指定して絞れます。':'対象 '+total+'Rを表示。';\n  if(!total){const empty=document.createElement('p');empty.className='muted';\n   empty.textContent='表示する予想下書きや購入記録がありません。';$('reviewDetails').append(empty);}\n  for(const {group,parts,outcome,conflict} of model.details.slice(0,60)){\n   const row=document.createElement('div');row.className='review-row';\n   const title=document.createElement('strong');\n   title.textContent=group.date+' '+group.track+group.race+'R';\n   row.append(title);\n   const outcomeText=document.createElement('p');\n   outcomeText.textContent=conflict?'着順メモが食い違っています。各記録を修正してな。':\n    outcome?'本人入力の着順 '+outcome.join('→'):'着順未入力';\n   outcomeText.className=conflict?'error':'muted';\n   row.append(outcomeText);\n   for(const {name,form,v} of parts){\n    const description=document.createElement('p');description.className='review-picks';\n    description.textContent=name+'｜1着 '+form.first.join('・')+'／2着 '+form.second.join('・')+\n      '／3着 '+form.third.join('・')+'｜'+statusText(v);\n    description.className+=v.status==='reviewed'&&v.exact?' good':\n      v.status==='reviewed'&&!v.exact?' miss':'';\n    row.append(description);\n   }\n   const route=document.createElement('a');\n   route.href='/my-tickets#select=v1&date='+encodeURIComponent(group.date)+\n    '&track='+encodeURIComponent(group.track)+'&race='+group.race;\n   route.textContent='このレースの記録を開く';\n   row.append(route);$('reviewDetails').append(row);\n  }\n }catch(err){\n  const warning=err instanceof Error?err.message:'端末内の保存内容を確認してください。';\n  $('reviewStatus').textContent='集計を停止しました：'+warning+\n   ' データを削除・上書きせず、バックアップを保管してください。';\n  $('reviewDraftStats').replaceChildren();$('reviewPurchaseStats').replaceChildren();\n  $('reviewDetails').replaceChildren();\n }\n}\nconst now=new Date(Date.now()+9*3600000).toISOString().slice(0,10);\n$('reviewDate').value=now;\n$('reviewScope').onchange=show;\n$('reviewDate').onchange=()=>{if($('reviewScope').value==='day')show();};\n$('reviewRefresh').onclick=show;\n// Safari may restore a prior page from BFCache; never show silently stale counts.\nif(typeof window!=='undefined')window.addEventListener('pageshow',event=>{if(event.persisted)show();});\nshow();\n})();"
